using FluentAssertions;
using TripCraft.Application.Workflows.Dtos;
using TripCraft.Application.Workflows.Validation;

namespace TripCraft.Tests.Workflows;

public class InternalAvailabilityBoundaryTests
{
    private static readonly DateOnly Date = new(2026, 10, 2);

    [Theory]
    [InlineData(0, false)]
    [InlineData(1, true)]
    [InlineData(50, true)]
    [InlineData(51, false)]
    public void Guide_capacity_accepts_inclusive_limits_for_a_same_day_trip(int pax, bool valid)
    {
        var result = new GuideAvailabilityQueryValidator().Validate(
            new GuideAvailabilityQuery { From = Date, To = Date, Language = "en", Pax = pax });
        result.IsValid.Should().Be(valid);
        if (!valid) result.Errors.Should().ContainSingle().Which.PropertyName.Should().Be("Pax");
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(1, true)]
    [InlineData(60, true)]
    [InlineData(61, false)]
    public void Vehicle_capacity_accepts_inclusive_limits_for_a_same_day_trip(int seats, bool valid)
    {
        var result = new VehicleAvailabilityQueryValidator().Validate(
            new VehicleAvailabilityQuery { From = Date, To = Date, Seats = seats });
        result.IsValid.Should().Be(valid);
        if (!valid) result.Errors.Should().ContainSingle().Which.PropertyName.Should().Be("Seats");
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(1, true)]
    [InlineData(30, true)]
    [InlineData(31, false)]
    public void Room_requests_accept_the_minimum_and_maximum_booking_sizes(int rooms, bool valid)
    {
        var result = new RoomAvailabilityQueryValidator().Validate(
            new RoomAvailabilityQuery { City = "Ella", Night = Date, Rooms = rooms });
        result.IsValid.Should().Be(valid);
        if (!valid) result.Errors.Should().ContainSingle().Which.PropertyName.Should().Be("Rooms");
    }
}
